//! Source-equivalent pure control-plane and immutable runtime configuration contracts.
//! Transport/database orchestration is covered separately; these tests never fake live authority.
use ai_platform_gateway::migration_agent::{Scope,control::project_child_event,runtime_contract as contract};
use serde_json::{Value,json};
fn scope()->Scope{Scope{tenant_id:"tenant-a".into(),user_id:"user-a".into(),session_id:"session-a".into()}}
fn connector(config:Value)->Value{json!({"agent_spec":{"channel":"api"},"capabilities":[{"type":"connector","id":"confluence_read","version":"v1","schema_hash":format!("sha256:{}","a".repeat(64)),"config":config}]})}
#[test]fn child_runtime_events_project_to_subagent_lifecycle(){let started=project_child_event(&json!({"event_type":"run_started","data":{"run_id":"child-turn","thread_id":"child-thread","session_id":"session-a","status":"running"}}),"parent-turn").unwrap();assert_eq!(started["event_type"],"subagent_started");assert_eq!(started["data"]["agent_id"],"child-thread");assert_eq!(started["data"]["parent_task_id"],"parent-turn");let finished=project_child_event(&json!({"event_type":"run_finished","data":{"run_id":"child-turn","thread_id":"child-thread","session_id":"session-a","status":"succeeded","exit":"succeeded"}}),"parent-turn").unwrap();assert_eq!(finished["event_type"],"subagent_finished");assert_eq!(finished["data"]["status"],"completed");let parent=json!({"event_type":"run_finished","data":{"run_id":"parent-turn"}});assert_eq!(project_child_event(&parent,"parent-turn"),Some(parent));assert!(project_child_event(&json!({"event_type":"thinking_delta","data":{"run_id":"child-turn"}}),"parent-turn").is_none());}
#[test]fn connector_rejects_secret_metadata(){assert!(contract::snapshot_allowlist(&connector(json!({"provider":"confluence","tool_name":"confluence_read","principal_type":"service_account","grant_id":"00000000-0000-0000-0000-000000000001","api_token":"must-not-cross-boundary"}))).is_err());}
#[test]fn builtin_empty_inherits_but_published_empty_remains_closed(){assert!(contract::snapshot_allowlist(&json!({"agent_spec":{"channel":"builtin"},"capabilities":[]})).unwrap().is_none());assert_eq!(contract::snapshot_allowlist(&json!({"agent_spec":{"channel":"api"},"capabilities":[]})).unwrap(),Some(vec![]));}
#[test]fn signed_connector_channel_preserved(){let a=contract::snapshot_allowlist(&connector(json!({"provider":"confluence"}))).unwrap().unwrap();assert_eq!(a,json!([{"type":"connector","name":"confluence_read","id":"confluence_read","version":"v1","schema_hash":format!("sha256:{}","a".repeat(64)),"connector_binding":{"binding_type":"catalog","provider":"confluence","tool_name":"confluence_read","principal_type":null,"grant_id":null,"channel":"api"}}]).as_array().unwrap().clone());}
#[test]fn mcp_snapshot_preserves_runtime_principal_binding(){let connection="00000000-0000-0000-0000-000000000001";let hash=format!("sha256:{}","a".repeat(64));let s=json!({"agent_spec":{"channel":"api"},"capabilities":[{"type":"mcp","id":"tenant_search","version":"v1","schema_hash":hash,"risk":"low","config":{"connection_id":connection,"principal_type":"user_delegated","risk":"low"}}]});let a=contract::snapshot_allowlist(&s).unwrap().unwrap();assert_eq!(a[0]["connector_binding"],json!({"binding_type":"grant","provider":"mcp","tool_name":"tenant_search","principal_type":"user_delegated","grant_id":null,"connection_id":connection,"schema_hash":hash,"risk_level":"low","channel":"api"}));}
#[test]fn responses_tool_controls_survive_readonly_snapshot(){let input=json!({"responses_tool_names":["search_knowledge_base"],"responses_tool_choice":{"type":"function","name":"search_knowledge_base"},"responses_parallel_tool_calls":false});let p=contract::readonly_payload(&input,&scope(),3).unwrap();for k in ["responses_tool_names","responses_tool_choice","responses_parallel_tool_calls"]{assert_eq!(p[k],input[k]);}}
#[test]fn native_multiagent_hides_legacy_loop_aliases(){let config=contract::runtime_model_config("http://gateway.test/model-plane","qwen3.7-plus",false);assert_eq!(config["features"]["multi_agent_v2"],json!({"enabled":true,"max_concurrent_threads_per_session":6}));assert_eq!(config["features"]["standalone_web_search"],false);assert_eq!(config["web_search"],"disabled");assert_eq!(contract::runtime_model_config("http://gateway.test/model-plane","qwen3.7-plus",true)["web_search"],"live");let tools:Vec<_>=["spawn_subagent","tool_search","context_compact","search_knowledge_base"].iter().map(|name|json!({"name":name,"description":"tool","schema":{"type":"object"},"read_only":*name!="context_compact"})).collect();let projected=contract::dynamic_tools(&json!({"tools":tools})).unwrap();assert_eq!(projected.iter().map(|v|v["name"].as_str().unwrap()).collect::<Vec<_>>(),vec!["search_knowledge_base"]);}
#[test]fn deferred_tools_require_exact_snapshot_allowlist(){let d=json!({"name":"document_write","description":"Write document","schema":{"type":"object"},"read_only":false,"id":"docs:document_write","version":"v1","schema_hash":format!("sha256:{}","a".repeat(64))});let mut r=json!({"tools":[],"mcp":[],"deferred":[d.clone()],"capability_allowlist":[{"type":"tool","name":d["name"],"id":d["id"],"version":d["version"],"schema_hash":d["schema_hash"]}]});assert_eq!(contract::dynamic_tools(&r).unwrap()[0]["name"],"document_write");r["capability_allowlist"][0]["schema_hash"]=json!(format!("sha256:{}","b".repeat(64)));assert!(contract::dynamic_tools(&r).unwrap().is_empty());}
#[test]fn attachment_refs_are_turn_scoped_and_do_not_change_catalog_fingerprint(){let r=contract::readonly_payload(&json!({"attachments":{"refs":["art_1111111111111111","art_2222222222222222"]}}),&scope(),7).unwrap();assert_eq!(r["attachment_tools"],json!([]));assert_eq!(r["items"][0]["payload"]["content_ref"],"art_1111111111111111");assert_eq!(r["items"][1]["payload"]["content_ref"],"art_2222222222222222");assert!(contract::dynamic_tools(&r).unwrap().is_empty());assert_eq!(contract::fingerprint(&json!({})),contract::fingerprint(&json!({"attachment_tools":[{"name":"read_attachment"}]})));}
fn platform_snapshot()->Value{json!({"agent_spec":{"developerInstructions":"stable platform instructions"},"capabilities":[{"type":"skill","id":"skill.audit","version":"v3","schema_hash":format!("sha256:{}","a".repeat(64)),"config":{"content_hash":"b".repeat(64),"permissions":["read:ledger"],"manifest":{"name":"audit","entrypoint":"db://skill/v3"}}},{"type":"connector","id":"docs.read","config":{"provider":"docs","grant_id":"grant-1","principal_type":"user_delegated"}}]})}
#[test]fn platform_config_freezes_skill_grant_and_attachment_identity(){let readonly=json!({"items":[{"kind":"attachment","payload":{"content_ref":"att-2"}},{"kind":"attachment","payload":{"content_ref":"att-1"}},{"kind":"attachment","payload":{"content_ref":"att-1"}}]});let c=contract::platform_config(&platform_snapshot(),&scope(),&readonly).unwrap();assert_eq!(c["skills"][0]["id"],"skill.audit");assert_eq!(c["skills"][0]["version"],"v3");assert_eq!(c["skills"][0]["content_hash"],format!("sha256:{}","b".repeat(64)));assert_eq!(c["tenant_grants"][0]["grant_id"],"grant-1");assert_eq!(c["attachments"][0]["ref"],"att-1");assert_eq!(c["attachments"][1]["ref"],"att-2");assert_eq!(c["instructions"]["dynamic_data_after_instructions"],true);assert_eq!(c,contract::platform_config(&platform_snapshot(),&scope(),&readonly).unwrap());}
#[test]fn platform_config_rejects_secrets_and_missing_skill_hash(){let mut bad=platform_snapshot();bad["capabilities"][1]["config"]["api_token"]=json!("secret");assert!(contract::platform_config(&bad,&scope(),&json!({})).is_err());let mut missing=platform_snapshot();missing["capabilities"][0].as_object_mut().unwrap().remove("schema_hash");missing["capabilities"][0]["config"].as_object_mut().unwrap().remove("content_hash");assert!(contract::platform_config(&missing,&scope(),&json!({})).is_err());}
